func TestTruncateBody(t *testing.T) {
	t.Parallel()

	const maxBytes = 4096

	cases := []struct {
		name        string
		input       []byte
		wantLen     int
		wantHasTail bool
	}{
		{"empty", nil, 0, false},
		{"under cap", []byte("hello"), 5, false},
		{"at cap", bytes.Repeat([]byte("a"), maxBytes), maxBytes, false},
		{"one over cap", bytes.Repeat([]byte("a"), maxBytes+1), maxBytes + 3, true},
		{"huge body", bytes.Repeat([]byte("a"), maxBytes*8), maxBytes + 3, true},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got := truncateBody(tc.input)
			if len(got) != tc.wantLen {
				t.Fatalf("len = %d, want %d", len(got), tc.wantLen)
			}
			if tc.wantHasTail && !strings.HasSuffix(got, "...") {
				t.Fatalf("want trailing %q", "...")
			}
			if !tc.wantHasTail && strings.HasSuffix(got, "...") {
				t.Fatalf("unexpected trailing %q in %q", "...", got)
			}
		})
	}
}

func TestTruncateBody_UTF8RuneAtBoundary(t *testing.T) {
	t.Parallel()

	// '€' is 3 bytes (0xE2 0x82 0xAC). Place it so the slice at byte 4096 cuts
	// mid-rune; strings.ToValidUTF8 should drop the partial rune cleanly rather
	// than emit U+FFFD or invalid UTF-8.
	prefix := strings.Repeat("a", 4094)
	body := []byte(prefix + "€" + strings.Repeat("b", 100))
	got := truncateBody(body)

	if !utf8.ValidString(got) {
		t.Fatalf("output is not valid UTF-8")
	}
	if strings.ContainsRune(got, utf8.RuneError) {
		t.Fatalf("output contains replacement rune U+FFFD")
	}
	if !strings.HasSuffix(got, "...") {
		t.Fatalf("want trailing %q", "...")
	}
	// Partial rune must be dropped, not replaced: 4094 valid bytes + "...".
	if want := 4094 + 3; len(got) != want {
		t.Fatalf("len = %d, want %d (partial rune should be dropped, not replaced)", len(got), want)
	}
}

func TestCacheKeyDelimitsSortedQueryParams(t *testing.T) {
	t.Parallel()

	c := &Client{BaseURL: "https://api.example.test"}
	collidingTwoParams := c.cacheKey("/titles", map[string]string{
		"country": "USAformat",
		"year":    "bluray",
	})
	collidingThreeParams := c.cacheKey("/titles", map[string]string{
		"country": "USA",
		"format":  "bluray",
		"year":    "",
	})
	if collidingTwoParams == collidingThreeParams {
		t.Fatalf("cache keys collided for adjacent query params: %q", collidingTwoParams)
	}

	first := c.cacheKey("/titles", map[string]string{"format": "4k", "country": "USA"})
	second := c.cacheKey("/titles", map[string]string{"country": "USA", "format": "4k"})
	if first != second {
		t.Fatalf("cache key should be deterministic regardless of map order: %q != %q", first, second)
	}
}

func TestGetWithHeadersValuesPreservesRepeatedQueryParams(t *testing.T) {
	t.Parallel()

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		got := r.URL.Query()["format"]
		if len(got) != 2 || got[0] != "blu-ray" || got[1] != "4k" {
			t.Fatalf("format query values = %#v, want [blu-ray 4k]", got)
		}
		if got := r.URL.Query().Get("country"); got != "US" {
			t.Fatalf("country = %q, want US", got)
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(server.Close)

	c := New(&config.Config{BaseURL: server.URL}, time.Second, 0)
	c.HTTPClient = server.Client()
	c.NoCache = true

	params := url.Values{
		"format":  []string{"blu-ray", "4k"},
		"country": []string{"US"},
	}
	if _, err := c.GetWithHeadersValues(context.Background(), "/titles", params, nil); err != nil {
		t.Fatalf("GetWithHeadersValues returned error: %v", err)
	}
}

func TestRedirect_CrossOriginStripsCustomCredentialHeaders(t *testing.T) {
	received := make(chan http.Header, 1)
	target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		received <- r.Header.Clone()
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(target.Close)

	primary := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, target.URL+"/final", http.StatusFound)
	}))
	t.Cleanup(primary.Close)

	c := New(&config.Config{
		BaseURL:       primary.URL,
		AuthHeaderVal: "Bearer primary-secret",
		Headers: map[string]string{
			"X-API-Key":       "config-secret",
			"Accept":          "accept-secret",
			"Accept-Encoding": "encoding-secret",
			"Content-Type":    "content-secret",
			"User-Agent":      "agent-secret",
		},
	}, time.Second, 0)
	c.NoCache = true
	_, err := c.GetWithHeaders(context.Background(), "/start", nil, map[string]string{"X-Endpoint-Credential": "endpoint-secret"})
	if err != nil {
		t.Fatalf("cross-origin redirect failed: %v", err)
	}

	headers := <-received
	for _, name := range []string{"Authorization", "Cookie", "X-API-Key", "X-Endpoint-Credential"} {
		if got := headers.Get(name); got != "" {
			t.Fatalf("cross-origin redirect target received %s=%q", name, got)
		}
	}
	for name, secret := range map[string]string{
		"Accept":          "accept-secret",
		"Accept-Encoding": "encoding-secret",
		"Content-Type":    "content-secret",
		"User-Agent":      "agent-secret",
	} {
		if got := headers.Get(name); got == secret {
			t.Fatalf("cross-origin redirect forwarded caller-configured %s", name)
		}
	}
	if got := headers.Get("Accept"); got != "application/json" {
		t.Fatalf("cross-origin redirect Accept = %q, want client default", got)
	}
	if got := headers.Get("User-Agent"); got != "soccer-goat-pp-cli/0.1.0" {
		t.Fatalf("cross-origin redirect User-Agent = %q, want client default", got)
	}
}

func TestRedirectRegeneratesBinaryAndBodyDefaults(t *testing.T) {
	original, err := http.NewRequest(http.MethodPost, "https://primary.example/test", strings.NewReader(`{}`))
	if err != nil {
		t.Fatal(err)
	}
	original.Header.Set("Accept", "*/*")
	redirected, err := http.NewRequest(http.MethodPost, "https://mirror.example/test", strings.NewReader(`{}`))
	if err != nil {
		t.Fatal(err)
	}
	redirected.Header.Set("Content-Type", "caller-secret")
	redirected.Header.Set("X-Secret", "caller-secret")
	stripCrossOriginRedirectHeaders(redirected, original)
	for name, want := range map[string]string{
		"Accept":       "*/*",
		"Content-Type": "application/json",
		"User-Agent":   "soccer-goat-pp-cli/0.1.0",
	} {
		if got := redirected.Header.Get(name); got != want {
			t.Errorf("regenerated %s = %q, want %q", name, got, want)
		}
	}
	if got := redirected.Header.Get("X-Secret"); got != "" {
		t.Fatal("redirect retained caller-supplied credential header")
	}
}

func TestSameOriginNormalizesDefaultPorts(t *testing.T) {
	for _, tc := range []struct {
		a, b string
		want bool
	}{
		{"https://example.com", "https://example.com:443", true},
		{"http://example.com", "http://example.com:80", true},
		{"https://example.com:8443", "https://EXAMPLE.com:8443", true},
		{"https://example.com", "https://example.com:8443", false},
		{"http://example.com", "https://example.com", false},
		{"https://example.com", "https://other.example.com", false},
		{"https://example.com", "invalid", false},
	} {
		if got := sameOrigin(tc.a, tc.b); got != tc.want {
			t.Errorf("sameOrigin(%q, %q) = %v, want %v", tc.a, tc.b, got, tc.want)
		}
	}
}

